"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["41393"],{49180(t){t.exports=JSON.parse('{"id":"FIN-657","slug":"retention-ratio","term":"Retention Ratio","also_known_as":[],"difficulty":"Intermediate","definition":"The retention ratio is the proportion of a company\'s net income that it keeps in the business rather than paying out as dividends. It equals one minus the dividend payout ratio.","explanation":["The retention ratio, also called the plowback ratio, shows how much of each year\'s profit is reinvested in the company.","For example, a company with net income of 100 million that pays 40 million in dividends retains 60 million. Its retention ratio is 60%.","Retained profits add to shareholders\' equity and fund investments such as new equipment, research, acquisitions or debt reduction. A high retention ratio is common for growing companies that have many attractive investment opportunities.","The retention ratio is a key ingredient in estimating how fast a company can grow without raising new capital. Multiplying the retention ratio by return on equity gives the sustainable growth rate. If a company retains 60% of its profits and earns an ROE of 12%, it can grow at about 7.2% a year using only its own profits, assuming its financial structure stays the same.","A high retention ratio is only valuable if the company invests the money well. Retaining profits and earning low returns on them can destroy value compared with paying them out to shareholders."],"note":"","total":1500,"prev":{"slug":"retained-earnings","term":"Retained Earnings"},"next":{"slug":"retirement","term":"Retirement"}}')}}]);